import React, { useState, useEffect } from 'react';
import { heroSlides } from '../mockData';
import SlideContent from './HeroSlider/SlideContent';
import SlideNavigation from './HeroSlider/SlideNavigation';
import SlideIndicators from './HeroSlider/SlideIndicators';

const HeroSlider = () => {
  const [currentSlide, setCurrentSlide] = useState(0);

  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentSlide((prev) => (prev + 1) % heroSlides.length);
    }, 5000);

    return () => clearInterval(timer);
    // heroSlides is a static import, so no need to include in dependencies
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const nextSlide = () => {
    setCurrentSlide((prev) => (prev + 1) % heroSlides.length);
  };

  const prevSlide = () => {
    setCurrentSlide((prev) => (prev - 1 + heroSlides.length) % heroSlides.length);
  };

  return (
    <div className="relative w-full h-[600px] overflow-hidden mt-20">
      {/* Slides */}
      {heroSlides.map((slide, index) => (
        <SlideContent
          key={slide.id}
          slide={slide}
          isActive={index === currentSlide}
        />
      ))}

      {/* Navigation Arrows */}
      <SlideNavigation onPrevious={prevSlide} onNext={nextSlide} />

      {/* Dots Indicator */}
      <SlideIndicators
        slides={heroSlides}
        currentSlide={currentSlide}
        onSlideChange={setCurrentSlide}
      />
    </div>
  );
};

export default HeroSlider;
